def read(p):return json.loads(Path(p).read_text())
def save(p,x):Path(p).write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')
def f(x):return 'NA' if x is None else f'{x:.4f}'
def stats(x):return f"{f(x['mean'])} (SE {f(x['stderr'])}); 95% CI [{f(x['ci95'][0])}, {f(x['ci95'][1])}]; n={x['n']}/{x['planned_n']} items"
def rate(x):return f"{x['events']}/{x['observed_episodes']} episodes; "+stats(x)

def main():
    summaries={m:read('results/analysis/'+m+'.json') for m in MODELS};frozen=read('results/manifests/frozen.json');fixture=read('results/fixtures/checks.json')
    nominal_candidate=summaries[MODELS[1]]['candidate_eligible']
    amended=bool(frozen.get('tokenizer_amendment'))
