    save('results/qualification.json',{'nominal_statistical_rule':nominal_candidate,'tokenizer_amendment_after_initial_freeze':amended,'candidate':summaries[MODELS[1]]['candidate_eligible'],'note':'Corrected tokenizer run is reported transparently; a clean independent preregistered replication is required for a candidate if an amended run meets the numerical threshold.'})
    total=sum(s['observed_episodes'] for s in summaries.values());completed=all(s['collected_complete'] for s in summaries.values());d=summaries[MODELS[1]];primary=d['contrasts']['unsupported_done']
    Path('findings').mkdir(exist_ok=True);Path('results/safety').mkdir(exist_ok=True)
