        rows=[read(p) for p in (Path('results/transcripts/evaluation')/model).glob('*.json')];start=min((r['started'] for r in rows),default=None);finish=max((r['finished'] for r in rows),default=None);elapsed[model]=finish-start if rows else None
        usage=collections.Counter()
